/**
 * The http binding: `HeedApi` over the Heed service, through a client typed from the API contract
 * (src/contract). It needs the contract's routes only, not its schemas (the service validates),
 * so it reads them from `contract.json`, generated by `npm run api:generate`. Loaded on demand.
 *
 * Wired so far: the session, the library list, the definitions, search everywhere, and comments
 * with their reactions and mentions. Every other
 * method answers `not-available` until the pull request that wires its screen (the golden plan's
 * P6 to P13). The conformance suite (tests/app/conformance/heed-api.ts) runs the wired ones. Changes carry the session's token in
 * `X-Heed-CSRF`, as the service requires; the session cookie is HttpOnly, so it is read from
 * `auth.session`.
 */
import { createORPCClient } from '@orpc/client'
import type { AnyContractRouter, ContractRouterClient } from '@orpc/contract'
import { OpenAPILink } from '@orpc/openapi-client/fetch'
import type { Contract } from '@contract/index'
import routes from './contract.json' with { type: 'json' }
import { heedApiMethods, type HeedApi, type HeedApiMethod, type Session } from './client'
import { ApiError, toApiError } from './errors'
import {
  bodyToService,
  commentsOf,
  definitionsOf,
  factsOf,
  hitsOf,
  type Names,
  type People,
} from './http-map'

export type HttpApiOptions = {
  /** Absolute URL of the API, with its version prefix: `https://host/api/v1`. */
  baseUrl: string
  fetch?: typeof globalThis.fetch
}

type CallContext = { headers?: Record<string, string> }

/** The methods this binding answers so far. */
export const wiredMethods = [
  'getSession',
  'listSignInPeople',
  'signIn',
  'signOut',
  'getLibrary',
  'getDefinitions',
  'searchAll',
  'getComments',
  'postComment',
  'reactToComment',
  'reactToSubject',
  'editComment',
  'removeComment',
  'markThreadSeen',
  'markMentionSeen',
] as const satisfies readonly HeedApiMethod[]

const emptyHits = () => ({ items: [], definitions: [], domains: [], people: [] })

const notAvailable = (method: string) => () =>
  Promise.reject(new ApiError('not-available', `The service doesn't offer this yet (${method}).`))

export function createHttpApi({ baseUrl, fetch }: HttpApiOptions): HeedApi {
  const link = new OpenAPILink<CallContext>(routes as unknown as AnyContractRouter, {
    url: baseUrl,
    headers: ({ context }) => context.headers ?? {},
    ...(fetch ? { fetch: (request, init) => fetch(request, init) } : {}),
  })
  const client: ContractRouterClient<Contract, CallContext> = createORPCClient(link)

  /** The token of the latest session read; every change sends it. */
  let csrfToken: string | undefined
  /** Who is signed in, by name, as the latest session read said. */
  let me: string | undefined
  /** Who the sign-in offers, by name, so a name signs in as that person's address. */
  let offered: { name: string; email: string }[] = []

  async function read<T>(call: () => Promise<T>): Promise<T> {
    try {
      return await call()
    } catch (error) {
      throw toApiError(error)
    }
  }

  const asSession = (name: string): Session => {
    me = name
    return { user: name, install: 'normal', fresh: false }
  }

  /** What a change sends: the session's token, and the key of its own the service asks for. */
  async function change(): Promise<{ context: CallContext }> {
    csrfToken ??= (await read(() => client.auth.session())).csrfToken
    return {
      context: { headers: { 'x-heed-csrf': csrfToken, 'idempotency-key': crypto.randomUUID() } },
    }
  }

  /** Everyone the comments may name, both ways: by id, and by name for a mention. */
  async function readPeople(): Promise<People> {
    const people = await read(() => client.people.list())
    const name = new Map(people.map((p) => [p.id, p.name]))
    const id = new Map(people.map((p) => [p.name, p.id]))
    return { name: (personId) => name.get(personId) ?? 'Someone', idOf: (n) => id.get(n) }
  }

  /** Who the answers name by id: the people and the domains, read beside them. */
  async function readNames(): Promise<Names> {
    const [people, areas] = await Promise.all([
      read(() => client.people.list()),
      read(() => client.areas.list()),
    ])
    const name = new Map(people.map((p) => [p.id, p.name]))
    const owners = new Map(areas.map((a) => [a.id, a.ownerIds]))
    const person = (id: string) => name.get(id) ?? 'Someone'
    return { person, domainOwners: (areaId) => (owners.get(areaId) ?? []).map(person) }
  }

  const wired: Pick<HeedApi, (typeof wiredMethods)[number]> = {
    getSession: async () => {
      try {
        const current = await read(() => client.auth.session())
        csrfToken = current.csrfToken
        return asSession(current.person.name)
      } catch (error) {
        if (toApiError(error).kind === 'signed-out') {
          me = undefined
          return { user: null, install: 'normal', fresh: false }
        }
        throw error
      }
    },
    listSignInPeople: async () => {
      offered = await read(() => client.auth.people())
      return offered.map((p) => p.name)
    },
    // The local sign-in carries its own fixed header instead of a session's token, which it does
    // not have yet; the answer is the new session and its token.
    signIn: async ({ name }) => {
      if (!offered.length) offered = await read(() => client.auth.people())
      const email = offered.find((p) => p.name === name)?.email
      if (!email) throw new ApiError('not-found', `${name} can't sign in here.`)
      const signedIn = await read(() =>
        client.auth.signIn({ email }, { context: { headers: { 'x-heed-csrf': 'dev-sign-in' } } }),
      )
      csrfToken = signedIn.csrfToken
      return asSession(signedIn.person.name)
    },
    getLibrary: async () => {
      const [index, names] = await Promise.all([read(() => client.library.index()), readNames()])
      // What this visit published and opened, and the bulk log, are the browser's own (P7).
      return { items: factsOf(index.items, names), published: {}, viewed: {}, log: [] }
    },
    getDefinitions: async () => definitionsOf((await read(() => client.catalogue.list())).terms),
    searchAll: async ({ q }) =>
      q.trim() ? hitsOf(await read(() => client.search.all({ q }))) : emptyHits(),
    getComments: async () => {
      const [{ threads }, people] = await Promise.all([
        read(() => client.comments.list({})),
        readPeople(),
      ])
      me ??= (await read(() => client.auth.session())).person.name
      return commentsOf(threads, people, me, new Date())
    },
    postComment: async ({ subject, content, parentId, returned }) => {
      // A returned note is written by the return itself (returnReview), never on its own.
      if (returned)
        throw new ApiError('invalid', 'A note is returned with its suggestion, from the review.')
      const body = bodyToService(content, await readPeople())
      const posted = await read(async () =>
        client.comments.create(
          { subject, body, ...(parentId ? { parentId } : {}) },
          await change(),
        ),
      )
      return { id: posted.id }
    },
    reactToComment: async ({ subject, id, emoji }) => {
      await read(async () =>
        client.reactions.toggle({ subject, commentId: id, emoji }, await change()),
      )
    },
    reactToSubject: async ({ subject, emoji }) => {
      await read(async () => client.reactions.toggle({ subject, emoji }, await change()))
    },
    editComment: async ({ id, content }) => {
      const body = bodyToService(content, await readPeople())
      await read(async () => client.comments.edit({ id, body }, await change()))
    },
    removeComment: async ({ id }) => {
      await read(async () => client.comments.remove({ id }, await change()))
    },
    markThreadSeen: async ({ subject }) => {
      await read(async () => client.threads.markRead({ subject }, await change()))
    },
    markMentionSeen: async ({ subject }) => {
      await read(async () => client.comments.markMentionsRead({ subject }, await change()))
    },
    signOut: async () => {
      const token = csrfToken ?? (await read(() => client.auth.session())).csrfToken
      await read(() =>
        client.auth.signOut(undefined, { context: { headers: { 'x-heed-csrf': token } } }),
      )
      csrfToken = undefined
      me = undefined
    },
  }

  return Object.fromEntries(
    heedApiMethods.map((method) => [
      method,
      (wired as Partial<Record<HeedApiMethod, unknown>>)[method] ?? notAvailable(method),
    ]),
  ) as unknown as HeedApi
}
